     1→import { Router } from 'express';
     2→import { randomUUID } from 'crypto';
     3→import { getDb } from '../db/database.js';
     4→import { AuthRequest, requireRole } from '../middleware/auth.js';
     5→
     6→export const exercisesRouter = Router();
     7→
     8→// List all exercises with summary stats
     9→exercisesRouter.get('/', (_req, res) => {
    10→  const db = getDb();
    11→  const exercises = db.prepare(`
    12→    SELECT e.id, e.date, e.name, e.notes, e.oe_link_enabled,
    13→      (SELECT COUNT(DISTINCT operator_id) FROM signal_reports WHERE exercise_id = e.id AND is_op_marker = 0) as participant_count,
    14→      (SELECT COUNT(*) FROM signal_reports WHERE exercise_id = e.id AND is_op_marker = 0 AND readability IS NOT NULL) as report_count
    15→    FROM exercises e ORDER BY e.date ASC
    16→  `).all();
    17→  res.json(exercises);
    18→});
    19→
    20→// Create exercise (admin only)
    21→exercisesRouter.post('/', requireRole('admin'), (req, res) => {
    22→  const { date, name, oe_link_enabled } = req.body;
    23→  if (!date || !name) {
    24→    res.status(400).json({ error: 'Datum und Name erforderlich' });
    25→    return;
    26→  }
    27→  const db = getDb();
    28→  const id = randomUUID();
    29→  db.prepare('INSERT INTO exercises (id, date, name, oe_link_enabled) VALUES (?, ?, ?, ?)').run(id, date, name, oe_link_enabled !== undefined ? (oe_link_enabled ? 1 : 0) : 1);
    30→  const exercise = db.prepare('SELECT * FROM exercises WHERE id = ?').get(id);
    31→  res.status(201).json(exercise);
    32→});
    33→
    34→// Get full exercise with reports
    35→exercisesRouter.get('/:id', (req, res) => {
    36→  const db = getDb();
    37→  const exercise = db.prepare('SELECT * FROM exercises WHERE id = ?').get(req.params.id);
    38→  if (!exercise) {
    39→    res.status(404).json({ error: 'Übung nicht gefunden' });
    40→    return;
    41→  }
    42→
    43→  const repeaters = db.prepare(`
    44→    SELECT er.*, r.short_name, r.site_name, r.band, r.callsign as repeater_callsign,
    45→      r.frequency_mhz, r.offset_mhz, r.ctcss_hz, r.burst_hz, r.type, r.is_linked,
    46→      r.bundesland_code, bl.name as bundesland_name
    47→    FROM exercise_repeaters er
    48→    JOIN repeaters r ON r.id = er.repeater_id
    49→    LEFT JOIN bundeslaender bl ON bl.code = r.bundesland_code
    50→    WHERE er.exercise_id = ?
    51→    ORDER BY r.bundesland_code, r.sort_order
    52→  `).all(req.params.id);
    53→
    54→  const reports = db.prepare(`
    55→    SELECT sr.*, o.callsign, o.name as operator_name, o.bezirk_code, o.bundesland_code,
    56→      r.short_name as repeater_name, r.bundesland_code as repeater_bundesland_code,
    57→      ep.abbreviation as einstiegspunkt_abbr, ep.site_name as einstiegspunkt_name
    58→    FROM signal_reports sr
    59→    JOIN operators o ON o.id = sr.operator_id
    60→    JOIN repeaters r ON r.id = sr.repeater_id
    61→    LEFT JOIN einstiegspunkte ep ON ep.id = sr.einstiegspunkt_id
    62→    WHERE sr.exercise_id = ?
    63→    ORDER BY r.bundesland_code, o.callsign
    64→  `).all(req.params.id);
    65→
    66→  const attendance = db.prepare(`
    67→    SELECT ea.*, o.callsign, o.name as operator_name, o.bezirk_code, o.bundesland_code
    68→    FROM exercise_attendance ea
    69→    JOIN operators o ON o.id = ea.operator_id
    70→    WHERE ea.exercise_id = ?
    71→    ORDER BY o.callsign
    72→  `).all(req.params.id);
    73→
    74→  res.json({ ...exercise, repeaters, reports, attendance });
    75→});
    76→
    77→// Update exercise notes/name (admin only)
    78→exercisesRouter.patch('/:id', requireRole('admin'), (req, res) => {
    79→  const db = getDb();
    80→  const { notes, name, oe_link_enabled, organisator } = req.body;
    81→  const updates: string[] = [];
    82→  const params: any[] = [];
    83→  if (notes !== undefined) { updates.push('notes = ?'); params.push(notes); }
    84→  if (name !== undefined) { updates.push('name = ?'); params.push(name); }
    85→  if (oe_link_enabled !== undefined) { updates.push('oe_link_enabled = ?'); params.push(oe_link_enabled ? 1 : 0); }
    86→  if (organisator !== undefined) { updates.push('organisator = ?'); params.push(organisator || null); }
    87→  if (updates.length === 0) {
    88→    res.status(400).json({ error: 'Keine Änderungen' });
    89→    return;
    90→  }
    91→  params.push(req.params.id);
    92→  db.prepare(`UPDATE exercises SET ${updates.join(', ')} WHERE id = ?`).run(...params);
    93→  const exercise = db.prepare('SELECT * FROM exercises WHERE id = ?').get(req.params.id);
    94→  res.json(exercise);
    95→});
    96→
    97→// Get exercise stats
    98→exercisesRouter.get('/:id/stats', (req, res) => {
    99→  const db = getDb();
   100→  const eid = req.params.id;
   101→  const totalParticipants = (db.prepare('SELECT COUNT(DISTINCT operator_id) as c FROM signal_reports WHERE exercise_id = ? AND is_op_marker = 0').get(eid) as any)?.c || 0;
   102→  const totalReports = (db.prepare('SELECT COUNT(*) as c FROM signal_reports WHERE exercise_id = ? AND is_op_marker = 0 AND readability IS NOT NULL').get(eid) as any)?.c || 0;
   103→  const perRepeater = db.prepare(`
   104→    SELECT r.short_name, COUNT(*) as count
   105→    FROM signal_reports sr
   106→    JOIN repeaters r ON r.id = sr.repeater_id
   107→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0 AND sr.readability IS NOT NULL
   108→    GROUP BY sr.repeater_id
   109→    ORDER BY r.sort_order
   110→  `).all(eid);
   111→
   112→  // Bezirk breakdown: participants + reports per bezirk, grouped by bundesland
   113→  const bezirkStats = db.prepare(`
   114→    SELECT bl.name as bundesland, bl.code as bundesland_code, bl.sort_order as bl_sort,
   115→      bz.code as bezirk_code, bz.name as bezirk_name, bz.is_capital,
   116→      COUNT(DISTINCT sr.operator_id) as participants,
   117→      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as reports
   118→    FROM signal_reports sr
   119→    JOIN operators o ON o.id = sr.operator_id
   120→    JOIN bezirke bz ON bz.code = o.bezirk_code
   121→    JOIN bundeslaender bl ON bl.code = bz.bundesland_code
   122→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
   123→    GROUP BY bz.code
   124→    ORDER BY bl.sort_order, bz.code
   125→  `).all(eid);
   126→
   127→  // Bundesland breakdown
   128→  const blStats = db.prepare(`
   129→    SELECT
   130→      COALESCE(bl.name, 'Sonstige') as bundesland,
   131→      o.bundesland_code,
   132→      COUNT(DISTINCT sr.operator_id) as participants,
   133→      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as reports
   134→    FROM signal_reports sr
   135→    JOIN operators o ON o.id = sr.operator_id
   136→    LEFT JOIN bundeslaender bl ON bl.code = o.bundesland_code
   137→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
   138→    GROUP BY o.bundesland_code
   139→    ORDER BY o.bundesland_code
   140→  `).all(eid);
   141→
   142→  // Participant list: all operators with their report counts
   143→  const participants = db.prepare(`
   144→    SELECT o.callsign, o.name, o.bezirk_code, o.bundesland_code,
   145→      bl.name as bundesland_name,
   146→      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as report_count
   147→    FROM signal_reports sr
   148→    JOIN operators o ON o.id = sr.operator_id
   149→    LEFT JOIN bundeslaender bl ON bl.code = o.bundesland_code
   150→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
   151→    GROUP BY sr.operator_id
   152→    ORDER BY bl.sort_order, o.bezirk_code, o.callsign
   153→  `).all(eid);
   154→
   155→  res.json({ totalParticipants, totalReports, perRepeater, bezirkStats, blStats, participants });
   156→});
   157→
   158→// Exercise repeaters management
   159→exercisesRouter.get('/:id/repeaters', (req, res) => {
   160→  const db = getDb();
   161→  const repeaters = db.prepare(`
   162→    SELECT er.*, r.short_name, r.site_name, r.band, r.callsign as repeater_callsign,
   163→      r.frequency_mhz, r.offset_mhz, r.ctcss_hz, r.burst_hz, r.type, r.is_linked, r.sort_order,
   164→      r.bundesland_code, bl.name as bundesland_name
   165→    FROM exercise_repeaters er
   166→    JOIN repeaters r ON r.id = er.repeater_id
   167→    LEFT JOIN bundeslaender bl ON bl.code = r.bundesland_code
   168→    WHERE er.exercise_id = ?
   169→    ORDER BY r.bundesland_code, r.sort_order
   170→  `).all(req.params.id);
   171→  res.json(repeaters);
   172→});
   173→
   174→exercisesRouter.post('/:id/repeaters', (req, res) => {
   175→  const db = getDb();
   176→  const { repeater_id, operator_callsign } = req.body;
   177→  try {
   178→    db.prepare('INSERT INTO exercise_repeaters (exercise_id, repeater_id, operator_callsign) VALUES (?, ?, ?)').run(req.params.id, repeater_id, operator_callsign || null);
   179→    res.status(201).json({ success: true });
   180→  } catch (e: any) {
   181→    if (e.message?.includes('UNIQUE') || e.message?.includes('PRIMARY')) {
   182→      res.status(409).json({ error: 'Umsetzer bereits aktiviert' });
   183→    } else {
   184→      throw e;
   185→    }
   186→  }
   187→});
   188→
   189→exercisesRouter.patch('/:id/repeaters/:rid', (req, res) => {
   190→  const db = getDb();
   191→  const { operator_callsign } = req.body;
   192→  db.prepare('UPDATE exercise_repeaters SET operator_callsign = ? WHERE exercise_id = ? AND repeater_id = ?')
   193→    .run(operator_callsign || null, req.params.id, req.params.rid);
   194→  res.json({ success: true });
   195→});
   196→
   197→exercisesRouter.delete('/:id/repeaters/:rid', requireRole('admin'), (req, res) => {
   198→  const db = getDb();
   199→  db.prepare('DELETE FROM exercise_repeaters WHERE exercise_id = ? AND repeater_id = ?')
   200→    .run(req.params.id, req.params.rid);
   201→  res.json({ success: true });
   202→});
   203→
   204→// Signal Reports CRUD
   205→exercisesRouter.get('/:id/reports', (req, res) => {
   206→  const db = getDb();
   207→  const reports = db.prepare(`
   208→    SELECT sr.*, o.callsign, o.name as operator_name, o.bezirk_code, o.bundesland_code,
   209→      r.short_name as repeater_name, r.bundesland_code as repeater_bundesland_code,
   210→      ep.abbreviation as einstiegspunkt_abbr, ep.site_name as einstiegspunkt_name
   211→    FROM signal_reports sr
   212→    JOIN operators o ON o.id = sr.operator_id
   213→    JOIN repeaters r ON r.id = sr.repeater_id
   214→    LEFT JOIN einstiegspunkte ep ON ep.id = sr.einstiegspunkt_id
   215→    WHERE sr.exercise_id = ?
   216→    ORDER BY sr.created_at DESC
   217→  `).all(req.params.id);
   218→  res.json(reports);
   219→});
   220→
   221→exercisesRouter.post('/:id/reports', (req, res) => {
   222→  const db = getDb();
   223→  const admin = (req as AuthRequest).admin!;
   224→  const { operator_id, repeater_id, readability, strength, db_over_s9, einstiegspunkt_id, is_op_marker, notes } = req.body;
   225→  console.log(`[report] POST exercise=${req.params.id} op=${operator_id} rep=${repeater_id} r=${readability} s=${strength} by=${admin.username}`);
   226→
   227→  if (!operator_id || !repeater_id) {
   228→    console.log('[report] REJECTED: missing operator_id or repeater_id');
   229→    res.status(400).json({ error: 'operator_id und repeater_id erforderlich' });
   230→    return;
   231→  }
   232→
   233→  try {
   234→    const result = db.prepare(`
   235→      INSERT INTO signal_reports (exercise_id, operator_id, repeater_id, readability, strength, db_over_s9, einstiegspunkt_id, is_op_marker, notes, entered_by)
   236→      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
   237→    `).run(req.params.id, operator_id, repeater_id, readability || null, strength || null, db_over_s9 || null, einstiegspunkt_id || null, is_op_marker ? 1 : 0, notes || null, admin.username);
   238→
   239→    // Auto-add attendance
   240→    db.prepare('INSERT OR IGNORE INTO exercise_attendance (exercise_id, operator_id, entered_by) VALUES (?, ?, ?)')
   241→      .run(req.params.id, operator_id, admin.username);
   242→
   243→    const report = db.prepare(`
   244→      SELECT sr.*, o.callsign, o.name as operator_name, o.bezirk_code, o.bundesland_code,
   245→        r.short_name as repeater_name, r.bundesland_code as repeater_bundesland_code,
   246→        ep.abbreviation as einstiegspunkt_abbr, ep.site_name as einstiegspunkt_name
   247→      FROM signal_reports sr
   248→      JOIN operators o ON o.id = sr.operator_id
   249→      JOIN repeaters r ON r.id = sr.repeater_id
   250→      LEFT JOIN einstiegspunkte ep ON ep.id = sr.einstiegspunkt_id
   251→      WHERE sr.id = ?
   252→    `).get(result.lastInsertRowid);
   253→
   254→    res.status(201).json(report);
   255→  } catch (e: any) {
   256→    if (e.message?.includes('UNIQUE')) {
